insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8004, 27, 'Vergütung und Dienstzeiten im praktischen Jahr (Bund)', 'Verlässliche Vergütung und Dienstzeiten verbessern die Bedingungen angehender Ärztinnen und Ärzte. Umfang, Finanzierung und tatsächliche Wirkung auf die Belastung hängen von der konkreten Regelung ab.', 'offen', null, 'bund', null, true, 'blind'),
  (8005, 27, 'Digitale Zugangsrechte für betriebliche Mitbestimmung (Bund)', 'Digitale Zugänge können Beteiligung erleichtern, ändern aber weder die Reichweite der Mitbestimmung noch unmittelbar Personal, Arbeitszeit oder Unterstützung.', 'offen', null, 'bund', null, true, 'blind'),
  (8006, 27, 'Arbeitsbedingungen und Mitsprache im Gesundheitswesen verbessern (Land)', 'Verlässlichere Arbeitszeiten und mehr Beteiligung setzen an Erholung und Einflussmöglichkeiten an. Die Zusage bleibt breit und lässt Umfang, Umsetzung und Finanzierung offen.', 'gemischt', 'https://www.who.int/publications/i/item/9789240053052', 'land', null, true, 'blind'),
  (8007, 27, 'Berufsbezogene Sprachförderung für Gesundheitsbeschäftigte (Land)', 'Berufsbezogene Sprachförderung kann Verständigungsprobleme im Arbeitsalltag mindern. Für ihre direkte Wirkung auf die Belastung von Beschäftigten und die nötigen Kapazitäten ist die Evidenz begrenzt.', 'offen', null, 'land', null, true, 'blind'),
  (8008, 27, 'Mitentscheidung bei Investitions- und Standortfragen (Land)', 'Verbindliche Beteiligung kann den Einfluss auf Arbeitsbedingungen und Veränderungsprozesse erhöhen. Ohne nähere Zuständigkeiten und Durchsetzungsrechte bleibt die erwartbare Wirkung unsicher.', 'offen', null, 'land', null, true, 'blind'),
  (8009, 27, 'Pflegepersonal gewinnen und zurückgewinnen (Bund)', 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'gemischt', 'https://www.who.int/publications/i/item/9789240003279', 'bund', null, true, 'blind'),
  (8010, 27, 'Gesetzliche Personalbemessung im Gesundheitswesen (Bund)', 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'gemischt', 'https://europepmc.org/article/MED/35780608', 'bund', null, true, 'blind'),
  (8011, 27, 'Gesundheitsfördernde Maßnahmen für Beschäftigte (Bund)', 'Gesundheitsförderung kann Beschäftigte unterstützen, verändert aber nicht zwingend hohe emotionale Anforderungen, geringe Mitsprache oder fehlende soziale Unterstützung am Arbeitsplatz.', 'gemischt', 'https://europepmc.org/article/MED/37893584', 'bund', null, true, 'blind'),
  (8012, 27, 'Tariftreue bei Bundesaufträgen und Subventionen (Bund)', 'Tarifbindung kann Entlohnung und Arbeitsbedingungen bei erfassten Auftragnehmenden verbessern. Die Reichweite hängt von Vergabeumfang, Kontrollen und der tatsächlichen Tarifabdeckung ab.', 'offen', null, 'bund', null, true, 'blind'),
  (8013, 27, 'Betriebliche Interessenvertretung unterstützen (Land)', 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'offen', null, 'land', null, true, 'blind'),
  (8014, 27, 'Karriere- und Entwicklungspfade in der Pflege (Bund)', 'Durchlässige Laufbahnen und neue Rollen können berufliche Anerkennung und Entwicklungsperspektiven verbessern. Sie brauchen Ausbildungsplätze, klare Befugnisse und passende Finanzierung und ersetzen keine ausreichende Besetzung.', 'gemischt', 'https://www.who.int/publications/i/item/9789240003279', 'bund', null, true, 'blind'),
  (8015, 27, 'Dokumentations- und Nachweispflichten vereinfachen (Bund)', 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'gemischt', 'https://europepmc.org/article/MED/33434273', 'bund', null, true, 'blind'),
  (8016, 27, 'Betriebsratsgründungen und Wahlen erleichtern (Bund)', 'Schutz von Initiierenden und leichtere Wahlen können betriebliche Mitsprache ermöglichen. Ob daraus spürbar mehr Einfluss auf Arbeitsbelastung folgt, hängt von tatsächlicher Gründung und Durchsetzung ab.', 'offen', null, 'bund', null, true, 'blind'),
  (8017, 27, 'Beschäftigte in Krankenhausgremien beteiligen (Land)', 'Mitwirkung in Planungs- und Leitungsgremien erhöht die Möglichkeit, Arbeitsbedingungen zu beeinflussen. Die Wirkung ist unklar, solange Aufgaben, Stimmrechte und Umsetzung der Beschlüsse nicht feststehen.', 'offen', null, 'land', null, true, 'blind'),
  (8018, 27, 'Berufliche Selbstvertretung der Pflege durch eine Pflegekammer (Land)', 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'offen', null, 'land', null, true, 'blind'),
  (8019, 27, 'Tarifbindung durch tarifrechtliche Erleichterungen fördern (Bund)', 'Erleichterte Tarifbindung und Allgemeinverbindlichkeit können die Reichweite ausgehandelter Entlohnung verbessern. Der Effekt auf die Belastung hängt von den vereinbarten Inhalten und der tatsächlichen Abdeckung ab.', 'offen', null, 'bund', null, true, 'blind'),
  (8020, 27, 'Professionelle Sprachmittlung im Gesundheitswesen finanzieren (Land)', 'Reviews zeigen bessere Kommunikation und Versorgungsqualität mit professioneller Sprachmittlung; eine direkte Entlastung der Beschäftigten ist weniger gut untersucht. Verfügbarkeit und Finanzierung bestimmen die Wirkung.', 'gemischt', 'https://europepmc.org/article/MED/17362215', 'land', null, true, 'blind'),
  (8021, 27, 'Behinderung betrieblicher Mitbestimmung sanktionieren (Land)', 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'offen', null, 'land', null, true, 'blind'),
  (8022, 27, 'Arbeitszeit verkürzen und Personalausgleich sicherstellen (Bund)', 'Kürzere Arbeitszeiten können Erholung verbessern, wenn die Arbeitsmenge nicht auf weniger Zeit verdichtet wird. Voller Lohnausgleich und zusätzlicher Personalausgleich sind kosten- und personalintensiv.', 'gemischt', 'https://europepmc.org/article/MED/30737987', 'bund', null, true, 'blind'),
  (8023, 27, 'Springerpools und planbare Einsätze im Gesundheitswesen (Bund)', 'Pools können kurzfristige Ausfälle auffangen und planbare Einsatzzeiten fördern. Modellierungen zeigen, dass flexible Kräfte eine ausreichende Grundbesetzung nicht ersetzen und bei knapper Verfügbarkeit wenig verlässlich sind.', 'gemischt', 'https://europepmc.org/article/MED/33677251', 'bund', null, true, 'blind'),
  (8024, 27, 'Schutz vor Gewalt und Belästigung im Gesundheitswesen (Land)', 'Schutzmaßnahmen können emotionale Belastungen und Gefährdungen mindern. Reviews betonen, dass Schulungen Teil eines umfassenden Schutzkonzepts mit Unterstützung und passenden Bedingungen sein müssen.', 'gemischt', 'https://europepmc.org/article/MED/33802868', 'land', null, true, 'blind'),
  (8025, 27, 'Entlastungstarifverträge refinanzieren und verbreitern (Bund)', 'Entlastungstarifverträge können Arbeitsbedingungen verbindlicher verbessern. Reichweite, Finanzierung und Durchsetzung sind offen; Tarifregeln allein schaffen keine zusätzlichen Arbeitskräfte.', 'offen', null, 'bund', null, true, 'blind'),
  (8026, 27, 'Pflegepersonal ausbilden und besser bezahlen (Bund)', 'Mehr ausgebildetes Personal kann Besetzungsengpässe mindern, bessere Bezahlung kann die Anerkennung stärken. Ausbildung wirkt zeitverzögert und beide Zusagen lassen Umfang und Finanzierung offen.', 'gemischt', 'https://www.who.int/publications/i/item/9789240003279', 'bund', null, true, 'blind'),
  (8027, 27, 'Praxisnahe und kostenfreie Ausbildung in Gesundheitsberufen (Bund)', 'Kostenfreie und praxisnahe Ausbildung kann Zugang und Nachwuchs fördern, führt aber erst nach Abschluss zu zusätzlicher Besetzung. Ausbildungs- und Finanzierungskapazitäten begrenzen das Tempo.', 'gemischt', 'https://www.who.int/publications/i/item/9789240003279', 'bund', null, true, 'blind'),
  (8028, 27, 'Gesetzlicher Jahresurlaub von sechs Wochen (Bund)', 'Mehr Urlaub ermöglicht zusätzliche Erholungszeit, verändert aber nicht unmittelbar Pausen und Belastung zwischen den Urlaubstagen. Personalvertretung während Abwesenheiten muss mitgedacht werden.', 'offen', null, 'bund', null, true, 'blind'),
  (8029, 27, 'Entlastungsvereinbarungen öffentlicher Arbeitgeber mit Gewerkschaften (Bund)', 'Verbindliche Schritte können Personalengpässe und Arbeitsbedingungen adressieren. Die Zusage nennt weder Mindeststandards noch Finanzierung oder Sanktionen bei Nichteinhaltung.', 'offen', null, 'bund', null, true, 'blind'),
  (8030, 27, 'Niedrigschwellige Beratung für Gesundheitsbeschäftigte (Bund)', 'Beratung kann bei Stress und psychischer Belastung helfen, beseitigt aber keine Ursachen wie Unterbesetzung oder ungünstige Dienstpläne. Reviews finden Nutzen individueller Ansätze, bei heterogenen Studien.', 'gemischt', 'https://europepmc.org/article/MED/37893584', 'bund', null, true, 'blind'),
  (8031, 27, 'Tarifverträge in Gesundheit und Pflege unterstützen (Bund)', 'Tarifverträge können Bezahlung und Bedingungen regeln; die bloße Unterstützung enthält aber keine konkrete Vorgabe zu Lohn, Arbeitszeit oder Entlastung.', 'offen', null, 'bund', null, true, 'blind'),
  (8032, 27, 'Sprachniveau C1 für medizinisches Fachpersonal verlangen (Bund)', 'Gute Sprachkenntnisse können Verständigungsprobleme begrenzen, ersetzen aber keine verfügbare Sprachmittlung in komplexen Fällen. Höhere Zugangshürden können zudem die Personalgewinnung erschweren.', 'gemischt', 'https://europepmc.org/article/MED/17362215', 'bund', null, true, 'blind'),
  (8033, 27, 'Betriebliche Gesundheitsprävention und Präventionspreise (Land)', 'Prävention kann Gesundheit und Aufmerksamkeit für Arbeitsbedingungen fördern, greift aber ohne konkrete organisatorische Änderungen die genannten Ursachen nur begrenzt an.', 'offen', null, 'land', null, true, 'blind'),
  (8034, 27, 'Personalbemessung, zusätzliche Pflegekräfte und stressfreie Schichtpläne (Bund)', 'Personalbemessung und planbare Schichten setzen direkt an Besetzung und Erholung an. Die geforderte Größenordnung, Refinanzierung und Umsetzung über mehrere Berufsgruppen erfordern erhebliche Ressourcen.', 'gemischt', 'https://europepmc.org/article/MED/35780608', 'bund', null, true, 'blind'),
  (8035, 27, 'Sabbatjahr mit Rückkehrrecht (Bund)', 'Ein Sabbatjahr kann einzelnen Beschäftigten Erholung ermöglichen, löst aber nicht die regelmäßigen Pausen- und Schichtprobleme. Vertretung, Anspruchsumfang und Finanzierung sind ungeklärt.', 'offen', null, 'bund', null, true, 'blind'),
  (8036, 27, 'Finanzierung des Personalaufwuchses sicherstellen (Bund)', 'Finanzierung ist Voraussetzung für zusätzliche Stellen, schafft diese aber ohne konkrete Mittel, Verteilung und Einstellungsplan nicht selbst. Umfang und dauerhafte Finanzierung sind offen.', 'offen', null, 'bund', null, true, 'blind'),
  (8037, 27, 'Landesförderung an Mitbestimmung koppeln (Land)', 'Förderbedingungen können Mitsprache bei geförderten Einrichtungen anreizen, erfassen aber nur einen Teil der Arbeitgeber und nennen keine konkreten Mitbestimmungsstandards.', 'offen', null, 'land', null, true, 'blind'),
  (8038, 27, 'KI-gestützte Dokumentation ausbauen (Bund)', 'Automatisierung kann Dokumentationszeit senken, kann aber durch Prüfung, Korrekturen und Integration neue Arbeit erzeugen. Reviews finden wenige, heterogene Interventionsstudien und keine verlässliche allgemeine Wirkung.', 'offen', 'https://europepmc.org/article/MED/39366661', 'bund', null, true, 'blind'),
  (8039, 27, 'Mitbestimmung in öffentlichen und kirchlichen Einrichtungen anpassen (Bund)', 'Einheitlichere Beteiligungsrechte können den Einfluss Beschäftigter stärken. Die nötigen Änderungen betreffen unterschiedliche Rechts- und Trägerstrukturen; ihre Wirkung auf Belastung ist nicht direkt belegt.', 'offen', null, 'bund', null, true, 'blind'),
  (8040, 27, 'Rechtsanspruch auf familienfreundliche Schichten (Bund)', 'Planbarere und passende Dienstzeiten können Erholung erleichtern. Reviews verbinden ungünstige Schichtmerkmale mit Müdigkeit, finden aber gemischte Befunde und belegen diesen konkreten Rechtsanspruch nicht direkt.', 'gemischt', 'https://europepmc.org/article/MED/30737987', 'bund', null, true, 'blind'),
  (8041, 27, 'Höchstarbeitszeit und Ruhezeiten flexibilisieren (Bund)', 'Flexiblere Grenzen können individuelle Modelle ermöglichen, garantieren aber weder Pausen noch Erholung und können längere Einsätze erleichtern. Die Forschung verbindet kurze Ruhezeiten mit Müdigkeit, während Gesamtergebnisse gemischt sind.', 'gemischt', 'https://europepmc.org/article/MED/30737987', 'bund', null, true, 'blind'),
  (8042, 27, 'Verfolgung von Angriffen auf Mitbestimmung stärken (Land)', 'Spezialisierte Ermittlungen können bestehende Rechte besser durchsetzen und abschrecken. Sie schaffen selbst keine neuen Beteiligungsrechte und hängen von Fällen, Personal und Verfahrensdauer ab.', 'offen', null, 'land', null, true, 'blind'),
  (8043, 27, 'Verbindliche Mitbestimmung bei Personalplanung und Arbeitsbedingungen (Bund)', 'Erzwingbare Beteiligung bei Personalbemessung, Gesundheitsschutz und Weiterbildung stärkt den Einfluss auf Arbeitsbedingungen. Ob sie Belastungen reduziert, hängt von Durchsetzung und verfügbaren Ressourcen ab.', 'gemischt', 'https://www.who.int/publications/i/item/9789240053052', 'bund', null, true, 'blind'),
  (8044, 27, 'Psychische Belastungen kontrollieren und Beschäftigte beteiligen (Land)', 'Kontrollen und Beteiligung können psychosoziale Risiken sichtbar machen und Verbesserungen anstoßen. Wirkung setzt wirksame Standards und Abhilfe voraus; Zuständigkeiten für Arbeitsschutzregeln sind zwischen Bund und Ländern verteilt.', 'gemischt', 'https://www.who.int/publications/i/item/9789240053052', 'land', null, true, 'blind'),
  (8045, 27, 'Dialogkonferenz für Betriebs- und Personalräte (Land)', 'Austausch kann Probleme sichtbar machen, verleiht aber ohne verbindliche Rechte oder Umsetzungspflichten keinen zusätzlichen Einfluss auf Arbeitsbedingungen.', 'offen', null, 'land', null, true, 'blind'),
  (8046, 27, 'Betriebliche Gesundheitsförderung in Gesundheitsfachberufen (Land)', 'Förderprogramme können Prävention und gesundheitsfördernde Arbeitsbedingungen unterstützen. Ohne konkrete Vorgaben zu Personal, Arbeitszeit oder Einfluss bleibt die Wirkung auf die benannten Belastungsursachen begrenzt.', 'gemischt', 'https://www.who.int/publications/i/item/9789240053052', 'land', null, true, 'blind'),
  (8047, 27, 'Digitale Anwendungen, Automatisierung und Robotik zur Entlastung (Bund)', 'Technik kann einzelne Aufgaben erleichtern, aber die Maßnahme benennt weder Anwendungen noch Einsatzbedingungen. Einführungs-, Wartungs- und Kontrollaufwand kann einen Teil der erhofften Entlastung aufzehren.', 'offen', null, 'bund', null, true, 'blind'),
  (8048, 27, 'Mitbestimmung durch öffentliche Trägerschaft sichern (Land)', 'Rückgängigmachung von Ausgründungen kann Mitbestimmungswege wiederherstellen, betrifft aber nur bestimmte Einrichtungen und erfordert erhebliche organisatorische sowie finanzielle Schritte.', 'offen', null, 'land', null, true, 'blind'),
  (8049, 27, 'Leistungsgerechte Vergütung in Gesundheitsberufen (Bund)', 'Angemessene Bezahlung kann das Verhältnis von Einsatz und Belohnung verbessern. Ohne Maßstab, Betrag und Finanzierungsweg bleibt der Umfang unbestimmt; leistungsbezogene Anreize können zusätzliche Belastung erzeugen.', 'gemischt', null, 'bund', null, true, 'blind'),
  (8050, 27, 'Arbeitsschutz und Mitbestimmung bei Personalbemessung stärken (Bund)', 'Arbeitsschutz und verbindliche Beteiligung können Belastungen vorbeugen und Mitsprache stärken. Die konkrete Entlastung hängt von Standards, Kontrolle und tatsächlicher Personalverfügbarkeit ab.', 'gemischt', 'https://www.who.int/publications/i/item/9789240053052', 'bund', null, true, 'blind'),
  (8051, 27, 'Lohnlücke in der Pflege schließen (Bund)', 'Eine konkrete Lohnanhebung verbessert unmittelbar die finanzielle Belohnung für Pflegearbeit. Höhe, betroffene Beschäftigte und Refinanzierung sind nicht ausgeführt; höhere Bezahlung allein löst Überlastung nicht.', 'gemischt', 'https://www.who.int/publications/i/item/9789240003279', 'bund', null, true, 'blind'),
  (8052, 27, 'Vergütung nicht-dualer Gesundheitsausbildungen verbessern (Bund)', 'Vergütung kann die finanzielle Belastung während der Ausbildung senken, betrifft aber Auszubildende und nicht unmittelbar die Arbeitslast der bereits Beschäftigten. Finanzierungszuständigkeiten sind zu klären.', 'offen', null, 'bund', null, true, 'blind'),
  (8053, 27, 'Genossenschaften und Belegschaftsmodelle fördern (Land)', 'Solche Modelle können Beschäftigten mehr Mitsprache eröffnen, sind aber kein allgemeiner Hebel für Arbeitsbedingungen und erfordern freiwillige Gründungen sowie tragfähige Finanzierung.', 'offen', null, 'land', null, true, 'blind'),
  (8054, 27, 'Handlungsspielraum und Befugnisse der Pflegefachkräfte erweitern (Land)', 'Mehr fachlicher Spielraum kann Einfluss auf die eigene Arbeit stärken. Zusätzliche Verantwortung kann zugleich Anforderungen erhöhen; Zuständigkeiten und Qualifikationen müssen klar geregelt sein.', 'gemischt', 'https://www.nationalacademies.org/publications/25982', 'land', null, true, 'blind'),
  (8055, 27, 'Arbeitszeit und Ruhezeiten verbindlich begrenzen (Bund)', 'Begrenzte Arbeitszeiten und ausreichende Ruhe können Müdigkeit reduzieren; Reviews stützen den Zusammenhang, zeigen aber teils gemischte Ergebnisse. Ohne Ausgleich kann die Arbeitsmenge pro Schicht steigen.', 'gemischt', 'https://europepmc.org/article/MED/30737987', 'bund', null, true, 'blind'),
  (8056, 27, 'Gesetzlichen Mindestlohn anheben und dynamisieren (Bund)', 'Ein höherer Mindestlohn verbessert die Entlohnung der davon erfassten Beschäftigten, erreicht aber viele qualifizierte Gesundheitsberufe nicht direkt und verändert Arbeitsbelastung oder Personalbesetzung nicht.', 'offen', null, 'bund', null, true, 'blind'),
  (8057, 27, 'Zusammenarbeit und Kompetenzen in Gesundheitsberufen erweitern (Bund)', 'Bessere Zusammenarbeit und erweiterte Befugnisse können Aufgaben verteilen und den Arbeitsablauf erleichtern. Ohne konkrete Zuständigkeiten oder Bezug zur Personalbemessung bleibt die Entlastung unsicher.', 'gemischt', 'https://www.nationalacademies.org/publications/25982', 'bund', null, true, 'blind'),
  (8058, 27, 'Abstimmung über eine Pflegekammer ermöglichen (Land)', 'Eine Abstimmung gibt Pflegekräften Einfluss auf die Einrichtung einer Selbstvertretung, ändert aber für sich genommen weder Arbeitsbedingungen noch Mitsprache am Arbeitsplatz.', 'offen', null, 'land', null, true, 'blind')
