  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (8059, 27, 11, null, 'Springerpools puffern Belastungsspitzen ab und planbare Einsatzzeiten verbessern die Arbeitsbedingungen.', '{2701,2702}', 8023, 2, 2, null, 'Pools können kurzfristige Ausfälle auffangen und planbare Einsatzzeiten fördern. Modellierungen zeigen, dass flexible Kräfte eine ausreichende Grundbesetzung nicht ersetzen und bei knapper Verfügbarkeit wenig verlässlich sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', 'https://europepmc.org/article/MED/33677251', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8060, 27, 11, null, 'Dokumentationsprozesse mit hohem Zeitaufwand vereinfachen.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8061, 27, 11, null, 'Durch Änderungen im Tarifvertragsgesetz die Bereitschaft zur Tarifbindung stützen.', '{2704}', 8019, 2, 3, null, 'Erleichterte Tarifbindung und Allgemeinverbindlichkeit können die Reichweite ausgehandelter Entlohnung verbessern. Der Effekt auf die Belastung hängt von den vereinbarten Inhalten und der tatsächlichen Abdeckung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8062, 27, 11, null, 'Online-Betriebsratssitzungen und -versammlungen als gleichwertige Alternative zu Präsenzformaten ermöglichen.', '{2705}', 8005, 1, 3, null, 'Digitale Zugänge können Beteiligung erleichtern, ändern aber weder die Reichweite der Mitbestimmung noch unmittelbar Personal, Arbeitszeit oder Unterstützung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8063, 27, 11, null, 'Digitale Zugangsrechte bei der betrieblichen Mitbestimmung klarstellen.', '{2705}', 8005, 1, 3, null, 'Digitale Zugänge können Beteiligung erleichtern, ändern aber weder die Reichweite der Mitbestimmung noch unmittelbar Personal, Arbeitszeit oder Unterstützung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8064, 27, 11, 'BE', 'Einrichtung einer Pflegekammer zur Weiterentwicklung des Pflegeberufs und Vertretung der Pflegeinteressen', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=100', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8065, 27, 11, 'ST', 'Pflegefachkräften mehr Kompetenzen und Verantwortung übertragen.', '{2705}', 8054, 2, 2, null, 'Mehr fachlicher Spielraum kann Einfluss auf die eigene Arbeit stärken. Zusätzliche Verantwortung kann zugleich Anforderungen erhöhen; Zuständigkeiten und Qualifikationen müssen klar geregelt sein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=28', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8066, 27, 12, null, 'Bedarfsgerechte Personalausstattung für alle Beschäftigtengruppen bundesweit einführen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8067, 27, 12, null, 'Zusammenarbeit aller Gesundheitsberufe und Durchlässigkeit stärken sowie Befugnisse von Pflegefachpersonen erweitern.', '{2701}', 8057, 1, 2, null, 'Bessere Zusammenarbeit und erweiterte Befugnisse können Aufgaben verteilen und den Arbeitsablauf erleichtern. Ohne konkrete Zuständigkeiten oder Bezug zur Personalbemessung bleibt die Entlastung unsicher.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8068, 27, 12, null, 'Weltweite Anwerbung und Integration von Fachkräften ausbauen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8069, 27, 12, null, 'Praxisnahe und kostenfreie Ausbildungen in Gesundheitsfachberufen fördern.', '{2701}', 8027, 1, 2, null, 'Kostenfreie und praxisnahe Ausbildung kann Zugang und Nachwuchs fördern, führt aber erst nach Abschluss zu zusätzlicher Besetzung. Ausbildungs- und Finanzierungskapazitäten begrenzen das Tempo.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8070, 27, 12, null, 'Mehr Freizeitausgleich schaffen, etwa durch eine verkürzte Wochenarbeitszeit.', '{2702}', 8022, 2, 1, null, 'Kürzere Arbeitszeiten können Erholung verbessern, wenn die Arbeitsmenge nicht auf weniger Zeit verdichtet wird. Voller Lohnausgleich und zusätzlicher Personalausgleich sind kosten- und personalintensiv.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8071, 27, 12, null, 'Vergütung und Dienstzeiten während des praktischen Jahres verlässlich regeln.', '{2702,2704}', 8004, 2, 2, null, 'Verlässliche Vergütung und Dienstzeiten verbessern die Bedingungen angehender Ärztinnen und Ärzte. Umfang, Finanzierung und tatsächliche Wirkung auf die Belastung hängen von der konkreten Regelung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8072, 27, 12, null, 'KI-gestützte Dokumentation ausbauen, um den Dokumentationsaufwand im Gesundheitswesen zu verringern.', '{2703}', 8038, 2, 2, null, 'Automatisierung kann Dokumentationszeit senken, kann aber durch Prüfung, Korrekturen und Integration neue Arbeit erzeugen. Reviews finden wenige, heterogene Interventionsstudien und keine verlässliche allgemeine Wirkung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/39366661', 'offen', '2026-10-06', false, true, 'blind'),
  (8073, 27, 12, null, 'Ordentliche Tarifverträge in Gesundheit und Pflege unterstützen.', '{2704}', 8031, 1, 3, null, 'Tarifverträge können Bezahlung und Bedingungen regeln; die bloße Unterstützung enthält aber keine konkrete Vorgabe zu Lohn, Arbeitszeit oder Entlastung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8074, 27, 12, null, 'Tarifgebundene Bezahlung bei Unternehmen mit Bundesaufträgen durchsetzen.', '{2704}', 8012, 2, 3, null, 'Tarifbindung kann Entlohnung und Arbeitsbedingungen bei erfassten Auftragnehmenden verbessern. Die Reichweite hängt von Vergabeumfang, Kontrollen und der tatsächlichen Tarifabdeckung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8075, 27, 12, null, 'Mitbestimmungsrechte der Betriebsräte bei Personalplanung, KI, Gesundheitsschutz und Weiterbildung ausbauen.', '{2705}', 8043, 2, 2, null, 'Erzwingbare Beteiligung bei Personalbemessung, Gesundheitsschutz und Weiterbildung stärkt den Einfluss auf Arbeitsbedingungen. Ob sie Belastungen reduziert, hängt von Durchsetzung und verfügbaren Ressourcen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8076, 27, 12, null, 'Zugang zu Weiterbildung und gesundheitsfördernden Maßnahmen für Beschäftigte in Gesundheitsberufen erleichtern.', '{2705}', 8011, 1, 3, null, 'Gesundheitsförderung kann Beschäftigte unterstützen, verändert aber nicht zwingend hohe emotionale Anforderungen, geringe Mitsprache oder fehlende soziale Unterstützung am Arbeitsplatz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/37893584', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8077, 27, 12, 'BE', 'Eine Konferenz für Betriebs- und Personalräte als Dialogforum schaffen.', '{2705}', 8045, 1, 3, null, 'Austausch kann Probleme sichtbar machen, verleiht aber ohne verbindliche Rechte oder Umsetzungspflichten keinen zusätzlichen Einfluss auf Arbeitsbedingungen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8078, 27, 12, 'BE', 'Die Verfolgung von Angriffen auf Mitbestimmung durch die Staatsanwaltschaft stärken.', '{2705}', 8042, 1, 3, null, 'Spezialisierte Ermittlungen können bestehende Rechte besser durchsetzen und abschrecken. Sie schaffen selbst keine neuen Beteiligungsrechte und hängen von Fällen, Personal und Verfahrensdauer ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8079, 27, 12, 'BE', 'Die Behinderung von Betriebsratsarbeit zu einem Offizialdelikt machen.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8080, 27, 12, 'BE', 'Eine unabhängige Arbeitnehmervertretung durch die Netzwerkstelle Gute Arbeit fördern.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8081, 27, 12, 'BE', 'Landesförderungen an Tarifbindung und Mitbestimmung koppeln.', '{2705}', 8037, 1, 2, null, 'Förderbedingungen können Mitsprache bei geförderten Einrichtungen anreizen, erfassen aber nur einen Teil der Arbeitgeber und nennen keine konkreten Mitbestimmungsstandards.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8082, 27, 12, 'BE', 'Ausgründungen rückgängig machen, die Mitbestimmung einschränken.', '{2705}', 8048, 1, 1, null, 'Rückgängigmachung von Ausgründungen kann Mitbestimmungswege wiederherstellen, betrifft aber nur bestimmte Einrichtungen und erfordert erhebliche organisatorische sowie finanzielle Schritte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=10', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8083, 27, 12, 'MV', 'Betriebsratsgründungen besser schützen und betriebliche Mitbestimmung stärken.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=23', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8084, 27, 12, 'ST', 'Das Land unterstützt die Gründung von Betriebsräten und informiert über Arbeitnehmerrechte.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=8', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8085, 27, 12, 'ST', 'Professionelle Sprachmittlung im Gesundheitswesen wird verlässlich finanziert.', '{2706}', 8020, 2, 2, null, 'Reviews zeigen bessere Kommunikation und Versorgungsqualität mit professioneller Sprachmittlung; eine direkte Entlastung der Beschäftigten ist weniger gut untersucht. Verfügbarkeit und Finanzierung bestimmen die Wirkung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8086, 27, 13, null, 'Höhere Personalschlüssel für Pflegekräfte umsetzen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8087, 27, 13, null, 'Wegen Überlastung ausgeschiedene Pflegefachkräfte mit einer Rückkehroffensive zurückgewinnen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8088, 27, 13, null, 'Dokumentationspflichten und Bürokratie in der Pflege auf ein Mindestmaß reduzieren.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=93', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8089, 27, 13, null, 'Durchlässige Weiterentwicklungswege und neue fachliche Rollen bis zum Masterniveau schaffen.', '{2704}', 8014, 2, 2, null, 'Durchlässige Laufbahnen und neue Rollen können berufliche Anerkennung und Entwicklungsperspektiven verbessern. Sie brauchen Ausbildungsplätze, klare Befugnisse und passende Finanzierung und ersetzen keine ausreichende Besetzung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8090, 27, 13, null, 'Gründung betrieblicher Interessenvertretungen unterstützen und Online-Wahlen ermöglichen.', '{2705}', 8016, 2, 3, null, 'Schutz von Initiierenden und leichtere Wahlen können betriebliche Mitsprache ermöglichen. Ob daraus spürbar mehr Einfluss auf Arbeitsbelastung folgt, hängt von tatsächlicher Gründung und Durchsetzung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8091, 27, 13, 'BE', 'Betriebliche Gesundheitsförderung und Präventionsprogramme für gesundheitsfördernde Arbeitsbedingungen in Gesundheitsfachberufen ausbauen.', '{2705}', 8046, 1, 3, null, 'Förderprogramme können Prävention und gesundheitsfördernde Arbeitsbedingungen unterstützen. Ohne konkrete Vorgaben zu Personal, Arbeitszeit oder Einfluss bleibt die Wirkung auf die benannten Belastungsursachen begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=208', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8092, 27, 13, 'BE', 'Aufbau einer Pflegekammer fördern und evaluieren, um die Interessenvertretung und Beteiligung der Pflegeberufe zu stärken.', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=214', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8093, 27, 13, 'BE', 'Ausreichende Sprachangebote für angeworbene Pflegefachkräfte bereitstellen.', '{2706}', 8007, 2, 2, null, 'Berufsbezogene Sprachförderung kann Verständigungsprobleme im Arbeitsalltag mindern. Für ihre direkte Wirkung auf die Belastung von Beschäftigten und die nötigen Kapazitäten ist die Evidenz begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=213', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8094, 27, 13, 'MV', 'Beschäftigte in Gesundheits- und Pflegeberufen vor Gewalt und Belästigung schützen.', '{2705}', 8024, 2, 2, null, 'Schutzmaßnahmen können emotionale Belastungen und Gefährdungen mindern. Reviews betonen, dass Schulungen Teil eines umfassenden Schutzkonzepts mit Unterstützung und passenden Bedingungen sein müssen.', 'https://gruene-mv.de/?wpdmdl=33772#page=58', 'https://europepmc.org/article/MED/33802868', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8095, 27, 13, 'ST', 'Beschäftigte durch Betriebsräte stärker an Entscheidungen beteiligen.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=76', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8096, 27, 13, 'ST', 'Eine Pflegeselbstvertretung schaffen, über die Pflegekräfte Berufsordnung und Interessen selbst mitgestalten.', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8097, 27, 13, 'ST', 'Genossenschaften und Belegschaftsmodelle als Formen betrieblicher Mitbestimmung fördern.', '{2705}', 8053, 1, 2, null, 'Solche Modelle können Beschäftigten mehr Mitsprache eröffnen, sind aber kein allgemeiner Hebel für Arbeitsbedingungen und erfordern freiwillige Gründungen sowie tragfähige Finanzierung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=89', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8098, 27, 14, null, 'Wöchentliche statt tägliche Höchstarbeitszeit einführen und Arbeitszeit- sowie Ruhezeitvorgaben flexibilisieren.', '{2702}', 8041, 0, 3, null, 'Flexiblere Grenzen können individuelle Modelle ermöglichen, garantieren aber weder Pausen noch Erholung und können längere Einsätze erleichtern. Die Forschung verbindet kurze Ruhezeiten mit Müdigkeit, während Gesamtergebnisse gemischt sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8099, 27, 14, null, 'Pflegeanbieter von unnötigen Nachweis- und Dokumentationspflichten befreien.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8100, 27, 14, null, 'Mehr Pflegefachkräfte im In- und Ausland gewinnen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8101, 27, 14, null, 'Digitale Anwendungen, Automatisierung und Robotik zur Entlastung des Pflegepersonals einsetzen.', '{2701}', 8047, 1, 2, null, 'Technik kann einzelne Aufgaben erleichtern, aber die Maßnahme benennt weder Anwendungen noch Einsatzbedingungen. Einführungs-, Wartungs- und Kontrollaufwand kann einen Teil der erhofften Entlastung aufzehren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8102, 27, 14, null, 'Eine ungekürzte, leistungsgerechte Vergütung für Gesundheitsberufe vorsehen.', '{2704}', 8049, 1, 2, null, 'Angemessene Bezahlung kann das Verhältnis von Einsatz und Belohnung verbessern. Ohne Maßstab, Betrag und Finanzierungsweg bleibt der Umfang unbestimmt; leistungsbezogene Anreize können zusätzliche Belastung erzeugen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8103, 27, 14, 'BE', 'Freiwilligen Zusammenschluss von Pflegekraeften zur Interessenvertretung unterstuetzen', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=116', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8104, 27, 14, 'MV', 'Handlungs- und Ermessensspielraum von Pflegekräften erweitern', '{2705}', 8054, 2, 2, null, 'Mehr fachlicher Spielraum kann Einfluss auf die eigene Arbeit stärken. Zusätzliche Verantwortung kann zugleich Anforderungen erhöhen; Zuständigkeiten und Qualifikationen müssen klar geregelt sein.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=50', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8105, 27, 15, null, 'Bundeseinheitliche gesetzliche Personalbemessung für alle pflegesensitiven Bereiche vorsehen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8106, 27, 15, null, 'Die Finanzierung des notwendigen Personalaufwuchses sicherstellen.', '{2701}', 8036, 2, 1, null, 'Finanzierung ist Voraussetzung für zusätzliche Stellen, schafft diese aber ohne konkrete Mittel, Verteilung und Einstellungsplan nicht selbst. Umfang und dauerhafte Finanzierung sind offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8107, 27, 15, null, 'Für medizinisches Fachpersonal eine fachliche und sprachliche Qualifikation auf Niveau C1 verlangen.', '{2706}', 8032, 1, 2, null, 'Gute Sprachkenntnisse können Verständigungsprobleme begrenzen, ersetzen aber keine verfügbare Sprachmittlung in komplexen Fällen. Höhere Zugangshürden können zudem die Personalgewinnung erschweren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=34', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8108, 27, 15, 'MV', 'Besseren gesetzlichen Schutz des medizinischen und pflegerischen Personals vor Gewalt umsetzen.', '{2705}', 8024, 2, 2, null, 'Schutzmaßnahmen können emotionale Belastungen und Gefährdungen mindern. Reviews betonen, dass Schulungen Teil eines umfassenden Schutzkonzepts mit Unterstützung und passenden Bedingungen sein müssen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=64', 'https://europepmc.org/article/MED/33802868', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8109, 27, 15, 'MV', 'Berufsbegleitende Sprachförderangebote für medizinisches Personal verankern und einheitliche Approbationsstandards konsequent anwenden.', '{2706}', 8007, 2, 2, null, 'Berufsbezogene Sprachförderung kann Verständigungsprobleme im Arbeitsalltag mindern. Für ihre direkte Wirkung auf die Belastung von Beschäftigten und die nötigen Kapazitäten ist die Evidenz begrenzt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8110, 27, 15, 'ST', 'Pflegekräfte sollen über die Einrichtung einer Pflegekammer abstimmen.', '{2705}', 8058, 1, 3, null, 'Eine Abstimmung gibt Pflegekräften Einfluss auf die Einrichtung einer Selbstvertretung, ändert aber für sich genommen weder Arbeitsbedingungen noch Mitsprache am Arbeitsplatz.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=244', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8111, 27, 16, null, 'Verbindliche Personalbemessung mit PPR 2.0, mehr Pflegepersonal und stressfreien Schichtplänen einführen.', '{2701,2702}', 8034, 2, 2, null, 'Personalbemessung und planbare Schichten setzen direkt an Besetzung und Erholung an. Die geforderte Größenordnung, Refinanzierung und Umsetzung über mehrere Berufsgruppen erfordern erhebliche Ressourcen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8112, 27, 16, null, 'Ehemalige Pflegekräfte und andere Gesundheitsbeschäftigte bundesweit zurückgewinnen und eine Ausbildungsoffensive starten.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8113, 27, 16, null, 'Entlastungstarifverträge unterstützen, refinanzieren und leichter allgemeinverbindlich machen.', '{2704}', 8025, 2, 2, null, 'Entlastungstarifverträge können Arbeitsbedingungen verbindlicher verbessern. Reichweite, Finanzierung und Durchsetzung sind offen; Tarifregeln allein schaffen keine zusätzlichen Arbeitskräfte.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8114, 27, 16, null, 'Niedrigschwellige Beratung und Unterstützung für Pflegekräfte, Rettungssanitäter*innen und andere belastende Gesundheitsberufe bereitstellen.', '{2705}', 8030, 1, 3, null, 'Beratung kann bei Stress und psychischer Belastung helfen, beseitigt aber keine Ursachen wie Unterbesetzung oder ungünstige Dienstpläne. Reviews finden Nutzen individueller Ansätze, bei heterogenen Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://europepmc.org/article/MED/37893584', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8115, 27, 16, null, 'Öffentliche Arbeitgeber sollen mit Gewerkschaften Entlastung und gute Arbeit vereinbaren, um Personalmangel zu beheben.', '{2701}', 8029, 2, 2, null, 'Verbindliche Schritte können Personalengpässe und Arbeitsbedingungen adressieren. Die Zusage nennt weder Mindeststandards noch Finanzierung oder Sanktionen bei Nichteinhaltung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8116, 27, 16, null, 'Arbeitsschutz stärken und Betriebsräten erzwingbare Mitbestimmung bei Personalbemessung und Belastungsvermeidung geben.', '{2705}', 8050, 2, 2, null, 'Arbeitsschutz und verbindliche Beteiligung können Belastungen vorbeugen und Mitsprache stärken. Die konkrete Entlastung hängt von Standards, Kontrolle und tatsächlicher Personalverfügbarkeit ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8117, 27, 16, null, 'Kürzere Arbeitszeiten mit vollem Lohnausgleich und notwendigem Personalausgleich unterstützen.', '{2701,2702}', 8025, 2, 2, null, 'Entlastungstarifverträge können Arbeitsbedingungen verbindlicher verbessern. Reichweite, Finanzierung und Durchsetzung sind offen; Tarifregeln allein schaffen keine zusätzlichen Arbeitskräfte.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8118, 27, 16, null, 'Acht-Stunden-Tag, mindestens elf Stunden Ruhezeit zwischen Schichten und höchstens 40 Wochenstunden sichern.', '{2702}', 8055, 2, 3, null, 'Begrenzte Arbeitszeiten und ausreichende Ruhe können Müdigkeit reduzieren; Reviews stützen den Zusammenhang, zeigen aber teils gemischte Ergebnisse. Ohne Ausgleich kann die Arbeitsmenge pro Schicht steigen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8119, 27, 16, null, 'Einen Rechtsanspruch auf familienfreundliche Schichten schaffen.', '{2702}', 8040, 2, 2, null, 'Planbarere und passende Dienstzeiten können Erholung erleichtern. Reviews verbinden ungünstige Schichtmerkmale mit Müdigkeit, finden aber gemischte Befunde und belegen diesen konkreten Rechtsanspruch nicht direkt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8120, 27, 16, null, 'Einen gesetzlichen Urlaubsanspruch von sechs Wochen pro Jahr einführen.', '{2702}', 8028, 1, 2, null, 'Mehr Urlaub ermöglicht zusätzliche Erholungszeit, verändert aber nicht unmittelbar Pausen und Belastung zwischen den Urlaubstagen. Personalvertretung während Abwesenheiten muss mitgedacht werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8121, 27, 16, null, 'Beschäftigten zweimal im Berufsleben ein Sabbatjahr mit Rückkehrrecht ermöglichen.', '{2702}', 8035, 1, 1, null, 'Ein Sabbatjahr kann einzelnen Beschäftigten Erholung ermöglichen, löst aber nicht die regelmäßigen Pausen- und Schichtprobleme. Vertretung, Anspruchsumfang und Finanzierung sind ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8122, 27, 16, null, 'Die Lohnlücke in der Kranken- und Altenpflege schließen und Pflegekräfte angemessen entlohnen.', '{2704}', 8051, 2, 2, null, 'Eine konkrete Lohnanhebung verbessert unmittelbar die finanzielle Belohnung für Pflegearbeit. Höhe, betroffene Beschäftigte und Refinanzierung sind nicht ausgeführt; höhere Bezahlung allein löst Überlastung nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8123, 27, 16, null, 'Den gesetzlichen Mindestlohn auf mindestens 60 Prozent des Medianlohns erhöhen und an dessen Entwicklung anpassen.', '{2704}', 8056, 1, 3, null, 'Ein höherer Mindestlohn verbessert die Entlohnung der davon erfassten Beschäftigten, erreicht aber viele qualifizierte Gesundheitsberufe nicht direkt und verändert Arbeitsbelastung oder Personalbesetzung nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8124, 27, 16, null, 'Die Mitbestimmung in öffentlichen und kirchlichen Einrichtungen an das Betriebsverfassungsgesetz anpassen.', '{2705}', 8039, 2, 2, null, 'Einheitlichere Beteiligungsrechte können den Einfluss Beschäftigter stärken. Die nötigen Änderungen betreffen unterschiedliche Rechts- und Trägerstrukturen; ihre Wirkung auf Belastung ist nicht direkt belegt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8125, 27, 16, null, 'Betriebsratswahlen erleichtern, ihre Behinderung konsequenter verfolgen und Initiator*innen besser schützen.', '{2705}', 8016, 2, 3, null, 'Schutz von Initiierenden und leichtere Wahlen können betriebliche Mitsprache ermöglichen. Ob daraus spürbar mehr Einfluss auf Arbeitsbelastung folgt, hängt von tatsächlicher Gründung und Durchsetzung ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8126, 27, 16, null, 'Nicht-duale Ausbildungen in Gesundheitsberufen besser entlohnen.', '{2704}', 8052, 1, 2, null, 'Vergütung kann die finanzielle Belastung während der Ausbildung senken, betrifft aber Auszubildende und nicht unmittelbar die Arbeitslast der bereits Beschäftigten. Finanzierungszuständigkeiten sind zu klären.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8127, 27, 16, 'BE', 'Beschäftigte in öffentlichen Krankenhäusern sollen in Planungs- und Leitungsgremien mitentscheiden.', '{2705}', 8017, 2, 2, null, 'Mitwirkung in Planungs- und Leitungsgremien erhöht die Möglichkeit, Arbeitsbedingungen zu beeinflussen. Die Wirkung ist unklar, solange Aufgaben, Stimmrechte und Umsetzung der Beschlüsse nicht feststehen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=136', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8128, 27, 16, 'BE', 'Psychische Belastungen sollen kontrolliert und Gesundheitsförderung sowie die Beteiligung der Beschäftigten an Verbesserungen verbindlich verankert werden.', '{2705}', 8044, 2, 2, null, 'Kontrollen und Beteiligung können psychosoziale Risiken sichtbar machen und Verbesserungen anstoßen. Wirkung setzt wirksame Standards und Abhilfe voraus; Zuständigkeiten für Arbeitsschutzregeln sind zwischen Bund und Ländern verteilt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=138', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8129, 27, 16, 'MV', 'Betriebs- und Personalräte stärken und das Personalvertretungsgesetz evaluieren.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8130, 27, 16, 'MV', 'Betriebliche Gesundheitsprävention fördern.', '{2705}', 8033, 1, 3, null, 'Prävention kann Gesundheit und Aufmerksamkeit für Arbeitsbedingungen fördern, greift aber ohne konkrete organisatorische Änderungen die genannten Ursachen nur begrenzt an.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8131, 27, 16, 'ST', 'Mitentscheidungsrechte der Betriebsräte bei Investitionen, Standortfragen und Digitalisierung ausweiten.', '{2705}', 8008, 2, 2, null, 'Verbindliche Beteiligung kann den Einfluss auf Arbeitsbedingungen und Veränderungsprozesse erhöhen. Ohne nähere Zuständigkeiten und Durchsetzungsrechte bleibt die erwartbare Wirkung unsicher.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8132, 27, 16, 'ST', 'Sanktionen gegen Union Busting und die Behinderung von Betriebsratsarbeit einführen.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8133, 27, 16, 'ST', 'Betriebsräte durch Bildung, Gesundheitsangebote und Weiterbildung fördern.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8134, 27, 16, 'ST', 'Ein Landesprogramm zur betrieblichen Mitbestimmung in kleinen und mittleren Unternehmen einrichten.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8135, 27, 16, 'ST', 'Einen landesweiten Sprachmittlerservice als Standard für den öffentlichen Dienst und die medizinische Versorgung einführen.', '{2706}', 8020, 2, 2, null, 'Reviews zeigen bessere Kommunikation und Versorgungsqualität mit professioneller Sprachmittlung; eine direkte Entlastung der Beschäftigten ist weniger gut untersucht. Verfügbarkeit und Finanzierung bestimmen die Wirkung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8136, 27, 17, null, 'Öffentliche Aufträge und Subventionen an die Zahlung von Tariflöhnen knüpfen.', '{2704}', 8012, 2, 3, null, 'Tarifbindung kann Entlohnung und Arbeitsbedingungen bei erfassten Auftragnehmenden verbessern. Die Reichweite hängt von Vergabeumfang, Kontrollen und der tatsächlichen Tarifabdeckung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8137, 27, 17, null, 'Die Allgemeinverbindlichkeit von Tarifverträgen erleichtern.', '{2704}', 8019, 2, 3, null, 'Erleichterte Tarifbindung und Allgemeinverbindlichkeit können die Reichweite ausgehandelter Entlohnung verbessern. Der Effekt auf die Belastung hängt von den vereinbarten Inhalten und der tatsächlichen Abdeckung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8138, 27, 17, null, 'Mehr Pflegepersonal ausbilden und besser bezahlen.', '{2704,2701}', 8026, 2, 2, null, 'Mehr ausgebildetes Personal kann Besetzungsengpässe mindern, bessere Bezahlung kann die Anerkennung stärken. Ausbildung wirkt zeitverzögert und beide Zusagen lassen Umfang und Finanzierung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8139, 27, 17, 'MV', 'Mitbestimmung als Teil verbesserter Arbeitsbedingungen zur Fachkräftebindung stärken', '{2705}', 8006, 2, 2, null, 'Verlässlichere Arbeitszeiten und mehr Beteiligung setzen an Erholung und Einflussmöglichkeiten an. Die Zusage bleibt breit und lässt Umfang, Umsetzung und Finanzierung offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=19', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8140, 27, 17, 'ST', 'Betriebsräte und Gewerkschaften an Investitions-, Standort- und Transformationsentscheidungen beteiligen.', '{2705}', 8008, 2, 2, null, 'Verbindliche Beteiligung kann den Einfluss auf Arbeitsbedingungen und Veränderungsprozesse erhöhen. Ohne nähere Zuständigkeiten und Durchsetzungsrechte bleibt die erwartbare Wirkung unsicher.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=22', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8141, 27, 17, 'ST', 'Behinderungen betrieblicher Mitbestimmung sanktionieren.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=22', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8583, 27, 18, null, 'Modellstudiengänge für Rettungsfachpersonal ausbauen und dauerhaft etablieren, weitere berufliche und akademische Weiterbildungsmöglichkeiten schaffen.', '{2704}', null, 1, 2, null, 'Fehlende Entwicklungsperspektiven gelten in einer Befragung von 814 Rettungskräften als Ausstiegsgrund; Studiengänge und Weiterbildung verbessern aber weder Pausen, Überstunden noch Besetzung. Hochschulen sind Ländersache, der Bund kann über Berufsrecht und Förderung beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=128', 'https://www.frontiersin.org/journals/health-services/articles/10.3389/frhs.2025.1548525/full', 'offen', '2026-10-07', false, true, 'blind'),
  (8584, 27, 18, null, 'Heilberufe erhalten Antrags- und Stimmrechte im Gemeinsamen Bundesausschuss.', '{2705}', null, 1, 2, null, 'Stimmrechte im G-BA geben Heilberufen Einfluss auf Richtlinien, die ihre Arbeit mitprägen, wirken aber nur mittelbar auf Mitsprache am Arbeitsplatz. Rechtlich per Bundesgesetz möglich, doch Fragen der demokratischen Legitimation und Vertretung sind ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=128', null, 'offen', '2026-10-07', false, true, 'blind');

select setval(pg_get_serial_sequence('public.massnahmen', 'id'), (select max(id) from public.massnahmen));

